"use client";

import { cn } from "@/lib/cn";

export type OutputState = "IDLE" | "LOADING" | "SUCCESS" | "ERROR";

interface Props {
  state: OutputState;
  output?: string | null;
  execTimeMs?: number | null;
}

/**
 * Shared output panel for the "custom input" / "custom output" tab in
 * Arena, Battleground, and Playground.
 */
export function OutputPanel({ state, output, execTimeMs }: Props) {
  return (
    <div className="rounded-xl bg-white p-3 ring-1 ring-neutral-200/70">
      <div className="flex items-center justify-between">
        <div className="text-[10.5px] font-medium uppercase tracking-[0.14em] text-neutral-400">
          stdout
        </div>
        <div className="flex items-center gap-2 text-[11px] text-neutral-500">
          {state === "LOADING" ? (
            <>
              <span className="h-1.5 w-1.5 rounded-full bg-neutral-400 animate-pulse" />
              running…
            </>
          ) : state === "SUCCESS" ? (
            <>
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
              ok{execTimeMs != null ? ` · ${execTimeMs}ms` : ""}
            </>
          ) : state === "ERROR" ? (
            <>
              <span className="h-1.5 w-1.5 rounded-full bg-red-500" />
              error
            </>
          ) : (
            <>
              <span className="h-1.5 w-1.5 rounded-full bg-neutral-300" />
              idle
            </>
          )}
        </div>
      </div>
      <pre
        className={cn(
          "mt-2 max-h-64 overflow-auto rounded-md p-3 text-[12.5px] leading-relaxed",
          state === "ERROR"
            ? "bg-red-50 text-red-800 ring-1 ring-red-100"
            : "bg-[var(--color-canvas)] text-neutral-800 ring-1 ring-neutral-200/70",
        )}
      >
        {output && output.length > 0
          ? output
          : state === "IDLE"
            ? "Run to see the output."
            : ""}
      </pre>
    </div>
  );
}
