"use client";

import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/cn";

interface Option {
  value: string;
  label: string;
}

interface Props {
  label?: string;
  value: string;
  onChange: (value: string) => void;
  options: Option[];
  className?: string;
}

/**
 * Native <select> in a design-system shell. Cheap, accessible, keyboard-native.
 */
export function Select({ label, value, onChange, options, className }: Props) {
  return (
    <label
      className={cn(
        "group inline-flex items-center gap-2 rounded-full bg-white px-3 py-1.5 text-[12px] font-medium text-neutral-700 ring-1 ring-neutral-200 focus-within:ring-neutral-500 hover:text-neutral-950",
        className,
      )}
    >
      {label ? (
        <span className="text-[11px] text-neutral-500">{label}</span>
      ) : null}
      <span className="relative flex items-center gap-1.5">
        <select
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="cursor-pointer appearance-none bg-transparent pr-4 text-[12.5px] font-medium text-neutral-950 focus:outline-none"
        >
          {options.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
        <ChevronDown
          aria-hidden
          className="pointer-events-none absolute right-0 h-3.5 w-3.5 text-neutral-500"
        />
      </span>
    </label>
  );
}
